// İnternetten hava durumu: open-meteo.com'dan sıcaklığı çek, saatle OLED'de göster.
#include <WiFi.h>
#include <HTTPClient.h>
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

const char* AG_ADI = "EvimWiFi";     // kendi Wi-Fi ağının adı
const char* PAROLA = "parola123";    // kendi Wi-Fi parolan
// Konum: İstanbul. Kendi şehrin için enlem ve boylamı değiştir.
const char* ADRES = "https://api.open-meteo.com/v1/forecast?latitude=41.01&longitude=28.97&current=temperature_2m";
const long SAAT_DILIMI = 3 * 3600;            // Türkiye: UTC+3
const unsigned long GUNCELLEME_MS = 60000;    // dakikada bir

Adafruit_SSD1306 ekran(128, 64, &Wire, -1);
float sicaklik = NAN;
unsigned long sonGuncelleme = 0;
bool ilkKez = true;

float sicaklikAl() {
  HTTPClient http;
  http.begin(ADRES);
  int kod = http.GET();
  float sonuc = NAN;
  if (kod == 200) {
    String json = http.getString();
    int bas = json.indexOf("\"current\"");
    int i = json.indexOf("\"temperature_2m\":", bas);
    if (bas >= 0 && i >= 0) sonuc = json.substring(i + 17).toFloat();
  } else {
    Serial.printf("HTTP hatasi: %d\n", kod);
  }
  http.end();
  return sonuc;
}

void setup() {
  Serial.begin(115200);
  Wire.begin(21, 22);
  ekran.begin(SSD1306_SWITCHCAPVCC, 0x3C);
  ekran.setTextColor(SSD1306_WHITE);
  ekran.clearDisplay();
  ekran.setCursor(0, 0);
  ekran.println("Wi-Fi baglaniyor...");
  ekran.display();

  WiFi.begin(AG_ADI, PAROLA);
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }
  Serial.println();
  Serial.print("IP: ");
  Serial.println(WiFi.localIP());
  configTime(SAAT_DILIMI, 0, "pool.ntp.org");
}

void loop() {
  if (ilkKez || millis() - sonGuncelleme > GUNCELLEME_MS) {
    ilkKez = false;
    sicaklik = sicaklikAl();
    sonGuncelleme = millis();
    Serial.printf("Disarisi: %.1f C\n", sicaklik);
  }

  ekran.clearDisplay();
  ekran.setTextSize(1);
  ekran.setCursor(0, 0);
  ekran.println("Istanbul");
  struct tm saat;
  if (getLocalTime(&saat)) {
    ekran.setTextSize(2);
    ekran.setCursor(0, 14);
    ekran.printf("%02d:%02d:%02d", saat.tm_hour, saat.tm_min, saat.tm_sec);
  }
  ekran.setTextSize(2);
  ekran.setCursor(0, 40);
  if (isnan(sicaklik)) {
    ekran.println("-- C");
  } else {
    ekran.print(sicaklik, 1);
    ekran.println(" C");
  }
  ekran.display();
  delay(1000);
}
